// 1. สร้าง Transaction ป้องกันข้อมูลการเงินผิดพลาด (All-or-Nothing Integrity)
using var transaction = await _db.Database.BeginTransactionAsync();
try {
    var order = new OrderHeader { Total = cart.Items.Sum(i => i.TotalPrice) };

    // 2. ยืนยันความถูกต้องของสลิปผ่าน API ภายนอก ก่อนบันทึกลงฐานข้อมูล
    if (await _paymentService.VerifySlipAsync(dto.SlipFile)) {
        _db.OrderHeaders.Add(order);
    }

    await _db.SaveChangesAsync();
    await transaction.CommitAsync();

    // 3. ยิงแจ้งเตือนออเดอร์ใหม่ไปที่หน้าจอห้องครัวทันที โดยไม่ต้อง Refresh หน้าเว็บ
    await _hubContext.Clients.Group("Kitchen").SendAsync("NewOrderReceived", order);
}
catch {
    await transaction.RollbackAsync(); // ยกเลิกคำสั่งทั้งหมดหากมีกระบวนการใดล้มเหลว
}

// ระบบตรวจสอบหมดอายุการจองอัตโนมัติ พร้อมจัดการข้อผิดพลาดด้วย Polly Retry Policy
var expiredCount = await Policy.Handle<Exception>()
    .WaitAndRetryAsync(3, attempt => TimeSpan.FromSeconds(10))
    .ExecuteAsync(async () => {

        // 1. ค้นหาการจองที่เกินเวลา ExpiryAt โดยใช้ Eager Loading ดึงข้อมูลรถที่เกี่ยวข้อง
        var expiredReservations = _db.Reservations.Include(r => r.Car)
            .Where(r => r.Status == "Pending" && r.ExpiryAt < DateTime.UtcNow)
            .ToList();

        // 2. เปลี่ยนสถานะการจองเป็น "หมดอายุ" และคืนสถานะรถกลับเป็น "พร้อมขาย" (Atomic Update)
        foreach (var res in expiredReservations) {
            res.Status = "Expired"; 
            res.Car.Status = "Available";
        }

        return await _db.SaveChangesAsync();
});

// ควบคุมการสร้างออเดอร์และการตัดสต็อกแบบ Atomic ป้องกันข้อมูลขาดหายกรณีเซิร์ฟเวอร์ขัดข้อง
using var transaction = await _dbContext.Database.BeginTransactionAsync();
try {
    // 1. ดึงข้อมูลสินค้าที่ลูกค้าต้องการสั่งซื้อ พร้อมลอค Row ไว้ไม่ให้คนอื่นแก้ไข (Pessimistic Concurrency)
    var productStock = await _dbContext.Products.FirstOrDefaultAsync(p => p.Id == productId);

    // 2. ตรวจสอบและตัดจำนวนสต็อกแบบทันที (Real-time Deduction)
    if (productStock.Quantity >= orderQuantity) {
        productStock.Quantity -= orderQuantity;
    }

    // 3. บันทึกข้อมูลใบสั่งซื้อและรายละเอียดลงหลายตารางพร้อมกันใน Transaction เดียว
    await _dbContext.SaveChangesAsync();
    await transaction.CommitAsync();
}
catch {
    await transaction.RollbackAsync(); // คืนค่าสต็อกและยกเลิกออเดอร์ทั้งหมดหากมีข้อผิดพลาด
}
